  "implementation": "def solve(case):
    min_size = case['min_cluster_size']
    clusters_in = case['clusters']
    parent_map = case['parent']

    retained = {}
    for cl in clusters_in:
        if cl['size'] >= min_size:
            retained[cl['cluster_id']] = cl

    if not retained:
        return {'clusters': [], 'selected_cluster_ids': []}

    children = {cid: [] for cid in retained}
    for cid, cl in retained.items():
        p = parent_map.get(cid)
        if p is not None and p in retained:
            children[p].append(cid)

    for cid, cl in retained.items():
        birth = cl['birth_lambda']
        stability = sum(max(0, exit - birth) for exit in cl['point_exit_lambdas'])
        cl['stability'] = stability

    candidates = sorted(retained.keys(), key=lambda cid: (-retained[cid]['stability'], cid))

    selected = []
    blocked = set()

    def get_retained_ancestors(cid):
        ancestors = []
        cur = parent_map.get(cid)
        while cur is not None:
            if cur in retained:
                ancestors.append(cur)
            cur = parent_map.get(cur)
        return ancestors

    def has_selected_descendant(cid):
        stack = children.get(cid, [])
        while stack:
            node = stack.pop()
            if node in selected_set:
                return True
            stack.extend(children.get(node, []))
        return False

    selected_set = set()
    for cid in candidates:
        if cid in blocked:
            continue
        if has_selected_descendant(cid):
            continue
        selected.append(cid)
        selected_set.add(cid)
        ancestors = get_retained_ancestors(cid)
        blocked.update(ancestors)

    selected_sorted = sorted(selected)
    clusters_output = []
    for cid in sorted(retained.keys()):
        cl = retained[cid]
        clusters_output.append({
            'cluster_id': cid,
            'size': cl['size'],
            'stability': cl['stability']
        })

    return {
        'clusters': clusters_output,
        'selected_cluster_ids': selected_sorted
    }"
}
